The approach is greedy: pair up the vertical photos, then build the slideshow by repeatedly picking a good next slide from a small candidate set.

**Reading input.** Each tag string is mapped to an integer ID, and each photo's tags are stored as a sorted vector of IDs.

**Pairing vertical photos.** Sort the vertical photos by tag count. Pair neighbours in that order, which keeps slides reasonably sized. A better approach would pair photos with few common tags, but the simple pairing is enough here. If there is an odd vertical photo, drop it.

**Building slides.** Each slide is a sorted tag vector, made by merging the two photos for a vertical pair (union).

**Ordering.** Greedy nearest-neighbour with a limited search:
- Keep an inverted index from tag to the slides containing it. Use only tags with a modest posting list, and skip huge lists.
- From the current slide, take candidates from the posting lists of its tags, scanning unused slides only. Cap the number of candidates examined at about 300–500. Lazily remove used slides from the lists by advancing a pointer per tag, so used slides at the front are skipped. Used entries in the middle remain, so scan with a cap.
- Score each candidate with the interest factor, using a merge-based intersection. Pick the best, and stop early if the score reaches the upper bound min(|A|,|B|)/2 style, or just cap the scan.
- If there are no candidates, fall back to the next unused slide in index order, using a global pointer.

To get diverse candidates, iterate over the tags of the current slide in order and, for each tag, scan up to K entries from the start of its list (the entries are mostly unused because of the pointer advancing). Total work is the sum of K over tags, so cap the total examined at about 400 per step. With 1e5 slides and about 400 candidates of roughly 20 tags each, that is about 1e5 × 400 × 30 = 1.2e9 operations, which is too heavy. Use a cap of 150 candidates instead, giving about 4.5e8, which is fine.

To keep the examined entries distinct, mark the visited candidates with a stamp array.

The start slide is slide 0. Output the slide order.

```cpp
#include <bits/stdc++.h>
using namespace std;
int main(){
    int n;
    scanf("%d",&n);
    unordered_map<string,int> mp;
    vector<vector<int>> t(n);
    vector<char> o(n);
    char buf[64];
    for(int i=0;i<n;i++){
        int m;
        scanf(" %c %d",&o[i],&m);
        for(int j=0;j<m;j++){
            scanf("%s",buf);
            auto it=mp.emplace(buf,(int)mp.size());
            t[i].push_back(it.first->second);
        }
        sort(t[i].begin(),t[i].end());
    }
    vector<vector<int>> st;
    vector<array<int,2>> ids;
    vector<int> v;
    for(int i=0;i<n;i++){
        if(o[i]=='H'){st.push_back(t[i]);ids.push_back({i,-1});}
        else v.push_back(i);
    }
    stable_sort(v.begin(),v.end(),[&](int a,int b){return t[a].size()<t[b].size();});
    for(size_t i=0;i+1<v.size();i+=2){
        vector<int> u;
        set_union(t[v[i]].begin(),t[v[i]].end(),t[v[i+1]].begin(),t[v[i+1]].end(),back_inserter(u));
        st.push_back(u);
        ids.push_back({v[i],v[i+1]});
    }
    int S=st.size();
    int T=mp.size();
    vector<vector<int>> post(T);
    for(int i=0;i<S;i++)for(int x:st[i])post[x].push_back(i);
    vector<int> ptr(T,0);
    vector<char> used(S,0);
    vector<int> stamp(S,-1);
    auto score=[&](int a,int b){
        auto&A=st[a];auto&B=st[b];
        size_t i=0,j=0;int c=0;
        while(i<A.size()&&j<B.size()){
            if(A[i]==B[j]){c++;i++;j++;}
            else if(A[i]<B[j])i++;else j++;
        }
        return min(c,(int)min(A.size()-c,B.size()-c));
    };
    vector<int> order;
    int cur=0;
    used[0]=1;
    order.push_back(0);
    int g=0;
    for(int step=1;step<S;step++){
        int best=-1,bs=-1,cnt=0;
        for(int x:st[cur]){
            auto&p=post[x];
            int&q=ptr[x];
            while(q<(int)p.size()&&used[p[q]])q++;
            int k=0;
            for(int idx=q;idx<(int)p.size()&&k<12;idx++){
                int c=p[idx];
                if(used[c]||stamp[c]==step)continue;
                stamp[c]=step;
                k++;cnt++;
                int s=score(cur,c);
                if(s>bs){bs=s;best=c;}
            }
            if(cnt>=150)break;
        }
        if(best<0){
            while(used[g])g++;
            best=g;
        }
        used[best]=1;
        order.push_back(best);
        cur=best;
    }
    printf("%d\n",S);
    for(int s:order){
        if(ids[s][1]<0)printf("%d\n",ids[s][0]);
        else printf("%d %d\n",ids[s][0],ids[s][1]);
    }
}
